#include "stdafx.h"#include <rsuPaths.h>#include <rsuErr.h>#include <macros/AutoCloser.h>#ifdef LINUX#include "LogFile.h"#endif // LINUXvoid ToLinuxPath (char *szPath){#ifdef LINUX	int nLen = lstrlen (szPath);	for (int i=0; i<nLen; i++)	{		if ( szPath[i] == '\\' )			szPath[i] = '/';	}#endif // LINUX}BYTE* OnDiskAllocator( HANDLE &hVarMapping, bool &bNewMem, DWORD Size, LPCSTR pszName, LPCSTR pszExt, bool bCreateAlways ){  hVarMapping = ::OpenFileMapping( FILE_MAP_ALL_ACCESS, FALSE, pszName );  bNewMem = false;  if( NULL==hVarMapping )  {    SYSTEM_INFO SI;    GetSystemInfo( &SI );    DWORD dwAlloc = ((Size / SI.dwAllocationGranularity)+1)*SI.dwAllocationGranularity;    ASS( dwAlloc>=Size );    char szPath[_MAX_PATH];    _makepath_s( szPath, NULL, rsuGetMemoryPath(), pszName, pszExt);	ToLinuxPath (szPath);#ifdef LINUX	CLogFile::Log ("OnDiskAllocator_1: szPath %s", szPath);#endif // LINUX    WIN32_FILE_ATTRIBUTE_DATA info;    bNewMem = true;    if( ::GetFileAttributesEx( szPath, GetFileExInfoStandard, &info ) )    {      if( !bCreateAlways )        dwAlloc = info.nFileSizeLow;      bNewMem = info.nFileSizeLow < dwAlloc;    }    else    {      if( !bCreateAlways )        return NULL;      bNewMem = true;    }    KAutoCloser<HANDLE> hVarFile( CreateFile( szPath,                                              GENERIC_READ|GENERIC_WRITE,                                              FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,                                              NULL,                                              OPEN_ALWAYS,                                              FILE_ATTRIBUTE_ARCHIVE,                                              NULL ),                                  CloseHandle);#ifdef LINUX	CLogFile::Log ("OnDiskAllocator_2: hVarFile %08lx", hVarFile);#endif // LINUX    if( NULL==hVarFile )      return NULL;    hVarMapping = CreateFileMapping( hVarFile, NULL, PAGE_READWRITE, 0, dwAlloc, pszName );#ifdef LINUX	CLogFile::Log ("OnDiskAllocator_3: hVarMapping %08lx", hVarMapping);#endif // LINUX    if( NULL==hVarMapping )      return NULL;  }  BYTE *pMem = (BYTE*)MapViewOfFileEx( hVarMapping, FILE_MAP_ALL_ACCESS, 0, 0, 0, NULL );#ifdef LINUX	CLogFile::Log ("OnDiskAllocator_4: pMem %08lx", pMem);#endif // LINUX  return pMem;}